package com.quickcart.service; import com.quickcart.entity.*; import com.quickcart.dto.ProductResponse; import com.quickcart.repository.*; import com.quickcart.exception.ApiException; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CatalogService {final CategoryRepository cr;final ProductRepository pr;CatalogService(CategoryRepository c,ProductRepository p){cr=c;pr=p;} public List<Category> categories(){return cr.findAll(Sort.by("displayOrder"));} public Page<ProductResponse> products(int page,int size){return pr.findByAvailableTrue(PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(ProductResponse::of);} public ProductResponse one(Long id){return pr.findById(id).filter(Product::isAvailable).map(ProductResponse::of).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Product not found"));} public List<ProductResponse> category(Long id){return pr.findByCategoryIdAndAvailableTrue(id).stream().map(ProductResponse::of).toList();} public List<ProductResponse> search(String q){if(q==null||q.isBlank())return List.of();return pr.search(q.trim()).stream().map(ProductResponse::of).toList();}}
